// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

// CSD transaction encoding (bincode, fixed-int, little-endian; compute-substrate
// src/types/mod.rs, verified against CSD's own serializer in test/fixtures):
//   version u32 | input_count u64 | inputs: prev_txid 32, vout u32, script_sig (u64 len + bytes)
//   | output_count u64 | outputs: value u64, script_pubkey 20 bytes (no length prefix)
//   | locktime u32 | app: u32 variant (0 None | 1 Propose{domain str, payload_hash 32, uri str, expires u64}
//   | 2 Attest{proposal_id 32, score u32, confidence u32}); str = u64 len + bytes
//
// CSD txid   = dsha256( version(4le) + input_count(8le) + inputs_with_empty_scripts + outputs_tail )
// Block hash = dsha256( version(4le) + prev(32) + merkle(32) + time(8le) + bits(4le) + nonce(4le) )
//
// How a CSD payment is proven (self-contained; no header oracle):
//   The settle call carries the payment transaction, its merkle path, the
//   block it's in, and the blocks after it. The contract checks that they
//   link up by hash, each has valid proof of work, each is at least as hard as
//   the difficulty the buyer signed (csdMaxTarget) on average (total work >=
//   k x the work of one block at csdMaxTarget), CSD's 60-second spacing
//   rule, and no block more than 2 h in the future. Faking k confirmations
//   therefore means mining k blocks' worth of work at that difficulty,
//   whatever else the fake chain does. The buyer (the party
//   at risk) picks the difficulty, typically ~3/4 of CSD's current difficulty
//   (target x 4/3), read from a CSD node; the seller checks it isn't above
//   the real difficulty before paying.

interface IERC20 {
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function transfer(address to, uint256 amount) external returns (bool);
}

interface IERC20Permit {
    function permit(address owner, address spender, uint256 value, uint256 deadline, uint8 v, bytes32 r, bytes32 s) external;
}

contract CsdUsdcSettlement {

    bytes32 public constant CSD_USDC_AUTH_TYPEHASH = keccak256(
        "CsdUsdcAuthorization(address buyer,address sellerUsdcRecipient,bytes32 sellerCsdScriptHash,"
        "bytes32 csdGenesisHash,bytes32 tradeIntentHash,uint256 csdAmount,address usdc,"
        "uint256 usdcAmount,uint256 minConfirmations,uint256 csdMaxTarget,uint256 executorFeeAmount,"
        "uint64 validAfter,uint64 validBefore,bytes32 nonce)"
    );

    // The buyer (the only party the confirmation wait protects) can waive it:
    // a signed early release pays the locked USDC to the seller right away,
    // without waiting for the CSD proof. The buyer carries the risk of the
    // CSD payment being reversed. Market makers use this to give sellers
    // near-instant USDC, and price that risk into their quotes.
    //
    // The release names what it pays (recipient, amount) so wallets can show
    // it, the CSD payment it accepts (that txid is then used up, exactly as a
    // proof would use it up), the lock it applies to (lockedAt; a release can't
    // carry over to a later re-lock), and a deadline.
    bytes32 public constant CSD_USDC_EARLY_RELEASE_TYPEHASH = keccak256(
        "CsdUsdcEarlyRelease(bytes32 authHash,address sellerUsdcRecipient,uint256 usdcAmount,"
        "bytes32 csdTxid,uint256 lockedAt,uint64 deadline)"
    );

    bytes32 private immutable DOMAIN_SEPARATOR;


    // Cap on USDC (incl. executor fees) locked across ALL open trades at once,
    // fixed at deployment. One fake CSD header chain can carry fake payments
    // for every open trade, so this bounds what such a chain could ever be
    // worth, whatever it costs to mine.
    uint256 public immutable maxTotalLocked;
    uint256 public totalLocked;

    // The one token this contract escrows (USDC), fixed at deployment.
    address public immutable usdcToken;

    // The CSD chain this contract settles against (its genesis block hash)
    bytes32 public immutable csdGenesisHash;

    // CSD consensus: PoW limit and minimum block spacing (compute-substrate src/params)
    uint32  public constant CSD_POW_LIMIT_BITS          = 0x1e00ffff;
    uint256 public constant CSD_MIN_BLOCK_SPACING_SECS  = 60;
    uint256 public constant CSD_MAX_FUTURE_DRIFT_SECS   = 2 hours;

    // One open lock per CSD receiving address. A CSD payment can't say which
    // trade it's for, so two open trades paying the same address could be
    // confused (one seller settling with the other's payment). Locks need a
    // proof that the buyer controls the address (CsdAddressProof), so nobody
    // can reserve someone else's address; a buyer uses a fresh address per trade.
    mapping(bytes32 => bytes32) public openLockForCsdAddress;   // sellerCsdScriptHash => authHash

    mapping(bytes32 => bool)    public finalizedAuthorization;
    // A CSD payment is used up per (txid, recipient address): a trade can only
    // use up payments to its own CSD address, so nobody can block someone
    // else's settlement by naming their transaction in an unrelated trade.
    mapping(bytes32 => bool)    public consumedCsdPayment;
    mapping(bytes32 => bool)    public usdcLocked;
    mapping(bytes32 => uint256) public lockedUntil;
    mapping(bytes32 => uint256) public lockedAmount;
    mapping(bytes32 => uint256) public lockedAt;
    mapping(bytes32 => bool)    public refundedAuthorization;   // a refunded authorization can't be locked again


    // Single cap: maximum 30 USDC per trade, at least 3 confirmations.
    // Conservative for launch — caps are grounded in real attack economics
    // against the current network hashrate. Buyers may ask for more
    // confirmations (up to 60), but that doesn't raise the cap: one fake
    // header chain can carry fake payments for every open trade at once, so
    // bigger per-trade caps would make such a chain worth more.
    // Changing these requires redeployment — intentional.
    uint256 public constant MIN_CONFIRMATIONS   = 3;
    uint256 public constant MAX_CONFIRMATIONS   = 60;
    uint256 public constant MAX_USDC_PER_TRADE  = 30_000_000;  // 30 USDC (6 decimals)
    // A trade must be worth something: an empty lock would reserve a CSD
    // address (see openLockForCsdAddress) for nothing but gas.
    uint256 public constant MIN_USDC_PER_TRADE  = 1_000_000;   // 1 USDC

    // Settlement window grows with the confirmations asked for: 10 minutes
    // plus 5 minutes per confirmation (2.5x CSD's 2-minute block time), so
    // the seller can always wait them out and submit the proof in time.
    // 3 confirmations = 25 minutes (as before), 20 = 110 minutes.
    uint256 public constant SETTLEMENT_LOCK_BASE_SECONDS     = 10 minutes;
    uint256 public constant SETTLEMENT_LOCK_PER_CONFIRMATION = 5 minutes;

    // A CSD payment only counts if its block is from after the lock (with
    // slack for CSD block timestamps running behind: median-time-past of 11
    // two-minute blocks is ~12 minutes). Otherwise an older, unrelated payment
    // to the same CSD address could be presented as this trade's payment.
    // Using a fresh CSD address per trade avoids the question entirely.
    uint256 public constant PAYMENT_TIME_TOLERANCE = 20 minutes;

    // ── Structs ───────────────────────────────────────────────────────────────

    struct CsdUsdcAuthorization {
        address buyer;
        address sellerUsdcRecipient;
        bytes32 sellerCsdScriptHash;   // 20-byte script left-aligned in bytes32
        bytes32 csdGenesisHash;
        bytes32 tradeIntentHash;
        uint256 csdAmount;
        address usdc;
        uint256 usdcAmount;
        uint256 minConfirmations;
        uint256 csdMaxTarget;          // every confirming block must have target <= this
        uint256 executorFeeAmount;
        uint64  validAfter;
        uint64  validBefore;
        bytes32 nonce;
    }

    struct CsdMerkleStep {
        bytes32 hash;
        bool    isLeft;               // true = sibling is on the left
    }

    struct CsdBlockHeader {
        uint32  version;
        bytes32 prev;
        bytes32 merkle;
        uint64  time;
        uint32  bits;
        uint32  nonce;
    }

    struct CsdSpvProof {
        bytes            txRaw;              // Full raw transaction bytes
        CsdMerkleStep[]  merkleBranch;       // Merkle inclusion proof
        CsdBlockHeader   header;             // Block header containing the tx
        CsdBlockHeader[] confirmationChain;  // The blocks after it, in order (minConfirmations - 1 or more)
    }

    // ── Events ────────────────────────────────────────────────────────────────

    event CsdUsdcSettled(
        bytes32 indexed authHash,
        bytes32 indexed csdTxid,
        address indexed buyer,
        address sellerUsdcRecipient,
        address usdc,
        uint256 usdcAmount,
        uint256 csdAmount
    );
    event CsdUsdcAuthorizationLocked(bytes32 indexed authHash, uint256 lockedUntil);
    event CsdUsdcAuthorizationFinalized(bytes32 indexed authHash, bytes32 indexed csdTxid);
    event CsdUsdcReleasedEarly(
        bytes32 indexed authHash,
        bytes32 indexed csdTxid,      // as named by the buyer, not verified
        address indexed buyer,
        address sellerUsdcRecipient,
        address usdc,
        uint256 usdcAmount,
        uint256 csdAmount
    );

    // ── Errors ────────────────────────────────────────────────────────────────

    error BadSignature();
    error AuthorizationExpired(bytes32 authHash);
    error TradeLimitExceeded();
    error AuthorizationAlreadyFinalized(bytes32 authHash);
    error AuthorizationLocked(bytes32 authHash, uint256 lockedUntil);
    error AuthorizationNotLocked(bytes32 authHash);
    error CsdTxAlreadyConsumed(bytes32 csdTxid);
    error CsdGenesisHashMismatch();
    error CsdMerkleInvalid();
    error CsdPaymentOutputNotFound();
    error CsdInsufficientPoW();
    error TransferFailed();
    error CsdBitsInvalid();
    error CsdBlockNotConfirmed();
    error CsdPaymentBeforeLock();
    error AuthorizationRefunded(bytes32 authHash);
    error TotalLockedLimitExceeded();
    error WrongToken();
    error CsdInsufficientWork(uint256 have, uint256 need);
    error CsdBlockInFuture();
    error CsdTxMalformed();
    error CsdCoinbaseNotSupported();
    error CsdAddressBusy(bytes32 openAuthHash);
    error CsdAddressProofInvalid();
    error CsdChainBroken();
    error CsdBlockTooSoon();
    error EarlyReleaseMismatch();
    error EarlyReleaseExpired();

    // ── Constructor ───────────────────────────────────────────────────────────

constructor(address _usdcToken, uint256 _maxTotalLocked, bytes32 _csdGenesisHash) {
    if (_usdcToken == address(0)) revert WrongToken();
    if (_csdGenesisHash == bytes32(0)) revert CsdGenesisHashMismatch();
    if (_maxTotalLocked < MAX_USDC_PER_TRADE) revert TradeLimitExceeded();
    usdcToken = _usdcToken;
    maxTotalLocked = _maxTotalLocked;
    csdGenesisHash = _csdGenesisHash;

    DOMAIN_SEPARATOR = keccak256(abi.encode(
        keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"),
        keccak256(bytes("AON CSD/USDC")),
        keccak256(bytes("4")),
        block.chainid,
        address(this)
    ));
}

    function domainSeparator() external view returns (bytes32) { return DOMAIN_SEPARATOR; }

    // ── EIP-712 hashing ───────────────────────────────────────────────────────

    function hashCsdUsdcAuthorization(
        CsdUsdcAuthorization calldata auth
    ) public view returns (bytes32) {
        return keccak256(abi.encodePacked(
            "\x19\x01",
            DOMAIN_SEPARATOR,
            // All fields are static, so abi.encode(struct) is exactly the
            // EIP-712 encoding of its fields in order
            keccak256(abi.encode(CSD_USDC_AUTH_TYPEHASH, auth))
        ));
    }

    // ── Lock ─────────────────────────────────────────────────────────────────
    // Buyer locks USDC to signal commitment. Seller can then safely send CSD.

    // Proof that the buyer controls the CSD receiving address: the address's
    // public key (64 bytes, uncompressed x||y) and its signature over
    // csdOwnershipDigest(authHash). CSD keys are secp256k1, like Ethereum's,
    // so ecrecover checks the signature; the address is hash160 of the
    // compressed key, as on CSD. This stops anyone from opening a trade on
    // someone else's CSD address (and so reserving it).
    struct CsdAddressProof {
        bytes pubKey;   // 64 bytes: x || y
        bytes sig;      // 65 bytes: r || s || v
    }

    struct UsdcPermit {
        uint256 deadline;
        uint8   v;
        bytes32 r;
        bytes32 s;
    }

    function csdOwnershipDigest(bytes32 authHash) public pure returns (bytes32) {
        return keccak256(abi.encodePacked("AON CSD/USDC: I control this CSD address for trade ", authHash));
    }

    function lockCsdUsdcAuthorization(
        CsdUsdcAuthorization calldata auth,
        bytes calldata authSig,
        CsdAddressProof calldata addressProof
    ) external {
        _lock(auth, authSig, addressProof);
    }

    // The same, with a USDC permit (EIP-2612) instead of a prior approval, so
    // the buyer only signs and anyone (an executor or market maker) submits.
    // The permit is for exactly usdcAmount + executorFeeAmount. If it was
    // already used (e.g. someone submitted it first), the lock still works as
    // long as the allowance is there.
    function lockCsdUsdcAuthorizationWithPermit(
        CsdUsdcAuthorization calldata auth,
        bytes calldata authSig,
        CsdAddressProof calldata addressProof,
        UsdcPermit calldata permit
    ) external {
        try IERC20Permit(usdcToken).permit(
            auth.buyer, address(this), auth.usdcAmount + auth.executorFeeAmount, permit.deadline, permit.v, permit.r, permit.s
        ) {} catch {}
        _lock(auth, authSig, addressProof);
    }

    function _lock(
        CsdUsdcAuthorization calldata auth,
        bytes calldata authSig,
        CsdAddressProof calldata addressProof
    ) internal {
        bytes32 authHash = hashCsdUsdcAuthorization(auth);

        if (usdcLocked[authHash])            revert AuthorizationLocked(authHash, lockedUntil[authHash]);
        if (finalizedAuthorization[authHash]) revert AuthorizationAlreadyFinalized(authHash);
        if (refundedAuthorization[authHash])  revert AuthorizationRefunded(authHash);
        if (block.timestamp < auth.validAfter || block.timestamp > auth.validBefore)
            revert AuthorizationExpired(authHash);
        if (_recover(authHash, authSig) != auth.buyer) revert BadSignature();
        _checkCsdAddressProof(auth.sellerCsdScriptHash, authHash, addressProof);
        if (auth.minConfirmations < MIN_CONFIRMATIONS)  revert TradeLimitExceeded();
        if (auth.minConfirmations > MAX_CONFIRMATIONS)  revert TradeLimitExceeded();
        if (auth.usdc != usdcToken)                     revert WrongToken();
        if (auth.csdGenesisHash != csdGenesisHash)      revert CsdGenesisHashMismatch();
        if (auth.csdMaxTarget == 0)                     revert CsdBitsInvalid();
        if (openLockForCsdAddress[auth.sellerCsdScriptHash] != bytes32(0))
            revert CsdAddressBusy(openLockForCsdAddress[auth.sellerCsdScriptHash]);
        // The cap covers everything locked for the trade, executor fee included
        if (auth.usdcAmount + auth.executorFeeAmount > MAX_USDC_PER_TRADE) revert TradeLimitExceeded();
        if (auth.usdcAmount < MIN_USDC_PER_TRADE || auth.csdAmount == 0) revert TradeLimitExceeded();

        // CEI: set state before external call to prevent reentrancy
        uint256 lockAmount = auth.usdcAmount + auth.executorFeeAmount;
        if (totalLocked + lockAmount > maxTotalLocked) revert TotalLockedLimitExceeded();
        totalLocked += lockAmount;
        uint256 until = block.timestamp + lockSecondsForConfirmations(auth.minConfirmations);
        if (until > auth.validBefore) until = auth.validBefore;

        lockedAmount[authHash] = lockAmount;
        usdcLocked[authHash]   = true;
        lockedUntil[authHash]  = until;
        lockedAt[authHash]     = block.timestamp;
        openLockForCsdAddress[auth.sellerCsdScriptHash] = authHash;

        if (!IERC20(auth.usdc).transferFrom(auth.buyer, address(this), lockAmount))
            revert TransferFailed();

        emit CsdUsdcAuthorizationLocked(authHash, until);
    }

    function _checkCsdAddressProof(bytes32 csdScriptHash, bytes32 authHash, CsdAddressProof calldata p) internal pure {
        if (p.pubKey.length != 64) revert CsdAddressProofInvalid();
        bytes32 x = bytes32(p.pubKey[0:32]);
        bytes32 y = bytes32(p.pubKey[32:64]);
        // CSD address = ripemd160(sha256(compressed pubkey))
        bytes1 prefix = (uint256(y) & 1) == 1 ? bytes1(0x03) : bytes1(0x02);
        bytes20 addr = ripemd160(abi.encodePacked(sha256(abi.encodePacked(prefix, x))));
        if (addr != bytes20(csdScriptHash) || uint256(csdScriptHash) << 160 != 0) revert CsdAddressProofInvalid();
        // The same key's Ethereum-style address must have signed
        address keyAddress = address(uint160(uint256(keccak256(p.pubKey))));
        if (_recover(csdOwnershipDigest(authHash), p.sig) != keyAddress) revert CsdAddressProofInvalid();
    }

    // ── Refund ────────────────────────────────────────────────────────────────
    // Returns USDC to buyer if the lock window expired without settlement.

    function refundExpiredLock(CsdUsdcAuthorization calldata auth) external {
        bytes32 authHash = hashCsdUsdcAuthorization(auth);

        if (finalizedAuthorization[authHash]) revert AuthorizationAlreadyFinalized(authHash);
        if (!usdcLocked[authHash])            revert AuthorizationNotLocked(authHash);
        if (block.timestamp <= lockedUntil[authHash])
            revert AuthorizationLocked(authHash, lockedUntil[authHash]);

        // CEI: clear state before transfer
        uint256 amount = lockedAmount[authHash];
        totalLocked -= amount;
        lockedAmount[authHash] = 0;
        usdcLocked[authHash]   = false;
        lockedUntil[authHash]  = 0;
        lockedAt[authHash]     = 0;
        delete openLockForCsdAddress[auth.sellerCsdScriptHash];
        refundedAuthorization[authHash] = true;

        if (!IERC20(auth.usdc).transfer(auth.buyer, amount)) revert TransferFailed();
    }

    // ── Early release ─────────────────────────────────────────────────────────
    // The buyer waives the confirmation wait for one locked trade: the USDC
    // goes to the seller now, without a CSD proof. Only the buyer's signature
    // over this exact authorization can do it; anyone may submit it (an
    // executor relays it and earns the executor fee, as with settlement).

    struct CsdUsdcEarlyRelease {
        bytes32 authHash;
        address sellerUsdcRecipient;
        uint256 usdcAmount;
        bytes32 csdTxid;      // the CSD payment the buyer accepts; used up like a proof would
        uint256 lockedAt;     // the lock this applies to
        uint64  deadline;
    }

    function hashCsdUsdcEarlyRelease(CsdUsdcEarlyRelease calldata r) public view returns (bytes32) {
        return keccak256(abi.encodePacked(
            "\x19\x01",
            DOMAIN_SEPARATOR,
            keccak256(abi.encode(
                CSD_USDC_EARLY_RELEASE_TYPEHASH,
                r.authHash, r.sellerUsdcRecipient, r.usdcAmount, r.csdTxid, r.lockedAt, r.deadline
            ))
        ));
    }

    function releaseEarly(
        CsdUsdcAuthorization calldata auth,
        CsdUsdcEarlyRelease calldata release,
        bytes calldata releaseSig
    ) external {
        bytes32 authHash = hashCsdUsdcAuthorization(auth);

        if (finalizedAuthorization[authHash]) revert AuthorizationAlreadyFinalized(authHash);
        if (!usdcLocked[authHash])            revert AuthorizationNotLocked(authHash);
        if (release.authHash != authHash
            || release.sellerUsdcRecipient != auth.sellerUsdcRecipient
            || release.usdcAmount != auth.usdcAmount
            || release.lockedAt != lockedAt[authHash]
            || release.csdTxid == bytes32(0)) revert EarlyReleaseMismatch();
        if (block.timestamp > release.deadline) revert EarlyReleaseExpired();
        if (_recover(hashCsdUsdcEarlyRelease(release), releaseSig) != auth.buyer) revert BadSignature();
        bytes32 paymentKey = csdPaymentKey(release.csdTxid, auth.sellerCsdScriptHash);
        if (consumedCsdPayment[paymentKey]) revert CsdTxAlreadyConsumed(release.csdTxid);

        // CEI: update all state before transfers
        consumedCsdPayment[paymentKey]   = true;
        finalizedAuthorization[authHash] = true;
        totalLocked -= lockedAmount[authHash];
        lockedAmount[authHash] = 0;
        usdcLocked[authHash]   = false;
        lockedUntil[authHash]  = 0;
        lockedAt[authHash]     = 0;
        delete openLockForCsdAddress[auth.sellerCsdScriptHash];

        if (!IERC20(auth.usdc).transfer(auth.sellerUsdcRecipient, auth.usdcAmount))
            revert TransferFailed();

        if (auth.executorFeeAmount > 0)
            if (!IERC20(auth.usdc).transfer(msg.sender, auth.executorFeeAmount))
                revert TransferFailed();

        // Not CsdUsdcAuthorizationFinalized: that event means a verified CSD
        // payment; here the payment is only the buyer's word.
        emit CsdUsdcReleasedEarly(
            authHash, release.csdTxid, auth.buyer, auth.sellerUsdcRecipient,
            auth.usdc, auth.usdcAmount, auth.csdAmount
        );
    }

    function csdPaymentKey(bytes32 csdTxid, bytes32 csdScriptHash) public pure returns (bytes32) {
        return keccak256(abi.encode(csdTxid, csdScriptHash));
    }

    // ── Limits ────────────────────────────────────────────────────────────────

    function lockSecondsForConfirmations(uint256 confirmations) public pure returns (uint256) {
        return SETTLEMENT_LOCK_BASE_SECONDS + confirmations * SETTLEMENT_LOCK_PER_CONFIRMATION;
    }

    // ── Settle ────────────────────────────────────────────────────────────────
    // Verifies the CSD payment on-chain via SPV, releases USDC to seller.

    function settleCsdUsdc(
        CsdUsdcAuthorization calldata auth,
        bytes calldata authSig,
        CsdSpvProof calldata spvProof
    ) external {
        bytes32 authHash = hashCsdUsdcAuthorization(auth);

        if (finalizedAuthorization[authHash]) revert AuthorizationAlreadyFinalized(authHash);
        if (!usdcLocked[authHash] || block.timestamp > lockedUntil[authHash])
            revert AuthorizationNotLocked(authHash);
        if (block.timestamp < auth.validAfter || block.timestamp > auth.validBefore)
            revert AuthorizationExpired(authHash);
        if (_recover(authHash, authSig) != auth.buyer) revert BadSignature();

        // The payment's block must be from after the lock (see PAYMENT_TIME_TOLERANCE)
        if (uint256(spvProof.header.time) + PAYMENT_TIME_TOLERANCE < lockedAt[authHash])
            revert CsdPaymentBeforeLock();

        bytes32 csdTxid = _verifyCsdSpv(spvProof, auth.sellerCsdScriptHash, auth.csdAmount, auth.minConfirmations, auth.csdMaxTarget);

        bytes32 paymentKey = csdPaymentKey(csdTxid, auth.sellerCsdScriptHash);
        if (consumedCsdPayment[paymentKey]) revert CsdTxAlreadyConsumed(csdTxid);

        // CEI: update all state before transfers
        consumedCsdPayment[paymentKey]  = true;
        finalizedAuthorization[authHash] = true;
        totalLocked -= lockedAmount[authHash];
        lockedAmount[authHash] = 0;
        usdcLocked[authHash]   = false;
        lockedUntil[authHash]  = 0;
        lockedAt[authHash]     = 0;
        delete openLockForCsdAddress[auth.sellerCsdScriptHash];

        if (!IERC20(auth.usdc).transfer(auth.sellerUsdcRecipient, auth.usdcAmount))
            revert TransferFailed();

        if (auth.executorFeeAmount > 0)
            if (!IERC20(auth.usdc).transfer(msg.sender, auth.executorFeeAmount))
                revert TransferFailed();

        emit CsdUsdcAuthorizationFinalized(authHash, csdTxid);
        emit CsdUsdcSettled(
            authHash, csdTxid, auth.buyer, auth.sellerUsdcRecipient,
            auth.usdc, auth.usdcAmount, auth.csdAmount
        );
    }

    // ── SPV verification ──────────────────────────────────────────────────────

    function _verifyCsdSpv(
        CsdSpvProof calldata proof,
        bytes32 expectedScriptHash,
        uint256 expectedAmount,
        uint256 minConfirmations,
        uint256 maxTarget
    ) internal view returns (bytes32 csdTxid) {
        // 1. The transaction is well-formed and pays the buyer's CSD address at least csdAmount
        _verifyCsdTx(proof.txRaw, expectedScriptHash, expectedAmount);
        csdTxid = _csdTxidFromRaw(proof.txRaw);

        // 2. It's in the payment block
        if (_csdMerkleRoot(csdTxid, proof.merkleBranch) != proof.header.merkle) revert CsdMerkleInvalid();

        // 3. The payment block and the blocks after it: linked, valid proof of
        //    work, CSD's spacing rule, not in the future, and in total at least
        //    minConfirmations blocks' worth of work at the signed difficulty
        if (1 + proof.confirmationChain.length < minConfirmations) revert CsdBlockNotConfirmed();
        (bytes32 prevHash, uint256 work) = _checkBlock(proof.header);
        uint64 prevTime = proof.header.time;
        for (uint256 i = 0; i < proof.confirmationChain.length; i++) {
            CsdBlockHeader calldata h = proof.confirmationChain[i];
            if (h.prev != prevHash) revert CsdChainBroken();
            if (uint256(h.time) < uint256(prevTime) + CSD_MIN_BLOCK_SPACING_SECS) revert CsdBlockTooSoon();
            uint256 w;
            (prevHash, w) = _checkBlock(h);
            work += w;
            prevTime = h.time;
        }
        uint256 need = minConfirmations * _workFromTarget(maxTarget);
        if (work < need) revert CsdInsufficientWork(work, need);
    }

    // The same block checks for any run of headers, for interfaces and
    // sellers to pre-check a proof, or to check real CSD blocks meet a
    // difficulty before relying on it. Returns the last block's hash.
    function checkHeaderChain(CsdBlockHeader[] calldata chain, uint256 maxTarget) external view returns (bytes32 lastHash) {
        if (chain.length == 0) revert CsdBlockNotConfirmed();
        uint256 work;
        (lastHash, work) = _checkBlock(chain[0]);
        for (uint256 i = 1; i < chain.length; i++) {
            if (chain[i].prev != lastHash) revert CsdChainBroken();
            if (uint256(chain[i].time) < uint256(chain[i - 1].time) + CSD_MIN_BLOCK_SPACING_SECS) revert CsdBlockTooSoon();
            uint256 w;
            (lastHash, w) = _checkBlock(chain[i]);
            work += w;
        }
        uint256 need = chain.length * _workFromTarget(maxTarget);
        if (work < need) revert CsdInsufficientWork(work, need);
    }

    // A header's hash and work, after checking its proof of work, CSD's PoW
    // limit, and that it isn't more than 2 h in the future (CSD's own rule)
    function _checkBlock(CsdBlockHeader calldata h) internal view returns (bytes32 blockHash, uint256 work) {
        uint256 target = _bitsToTarget(h.bits);
        if (target > _bitsToTarget(_powLimitBits())) revert CsdBitsInvalid();
        if (uint256(h.time) > block.timestamp + CSD_MAX_FUTURE_DRIFT_SECS) revert CsdBlockInFuture();
        blockHash = _csdHeaderHash(h);
        if (uint256(blockHash) > target) revert CsdInsufficientPoW();
        work = _workFromTarget(target);
    }

    // work_from_bits (compute-substrate src/chain/pow.rs): floor(2^256 / (target + 1))
    function _workFromTarget(uint256 target) internal pure returns (uint256) {
        if (target == type(uint256).max) return 1;
        uint256 d = target + 1;
        uint256 q = type(uint256).max / d;
        if (type(uint256).max % d == d - 1) q += 1;
        return q;
    }

    // CSD mainnet's PoW limit. Virtual only so the test suite can run the same
    // rules at an easy difficulty (test/TestContracts.sol).
    function _powLimitBits() internal pure virtual returns (uint32) { return CSD_POW_LIMIT_BITS; }

    // ── SPV primitives ────────────────────────────────────────────────────────

    // Compute CSD txid: dsha256 of tx bytes with input script_sigs replaced by empty
    function _csdTxidFromRaw(bytes calldata txRaw) internal pure returns (bytes32) {
        uint256 len = txRaw.length;
        require(len >= 12, "CSD_TX_TOO_SHORT");

        bytes memory buf = new bytes(len); // upper bound; trimmed before hashing
        uint256 boff = 0;
        uint256 off  = 0;

        // version (4 bytes)
        _cpCalldata(txRaw, off, buf, boff, 4); off += 4; boff += 4;

        // input_count (8 bytes u64le)
        uint64 inputCount = _readU64LE(txRaw, off);
        _cpCalldata(txRaw, off, buf, boff, 8); off += 8; boff += 8;

        for (uint64 i = 0; i < inputCount; i++) {
            require(off + 44 <= len, "CSD_TX_INPUT_OVF"); // 32 prev + 4 vout + 8 scriptLen
            // prev txid (32) + vout (4)
            _cpCalldata(txRaw, off, buf, boff, 36); off += 36; boff += 36;
            // read script_len, write 0 (empty script_sig), skip the actual script bytes
            uint64 scriptLen = _readU64LE(txRaw, off);
            off  += 8;
            boff += 8; // buf is zero-initialized so these 8 bytes are already 0
            require(off + scriptLen <= len, "CSD_TX_SCRIPT_OVF");
            off += scriptLen;
        }

        // outputs + tail
        uint256 tail = len - off;
        _cpCalldata(txRaw, off, buf, boff, tail); boff += tail;

        assembly { mstore(buf, boff) } // trim to actual length
        return sha256(abi.encodePacked(sha256(buf)));
    }

    // Parses the whole transaction strictly (every byte accounted for) and
    // checks one output pays >= expectedAmount to expectedScriptHash (the
    // 20-byte address, left-aligned in bytes32). Coinbase transactions are
    // refused: CSD keeps their input script in the txid, which this
    // contract's txid computation strips.
    function _verifyCsdTx(bytes calldata txRaw, bytes32 expectedScriptHash, uint256 expectedAmount) internal pure {
        uint256 len = txRaw.length;
        uint256 off = 4; // version
        if (len < off + 8) revert CsdTxMalformed();
        uint256 inputCount = _readU64LE(txRaw, off); off += 8;
        if (inputCount == 0) revert CsdTxMalformed();
        for (uint256 i = 0; i < inputCount; i++) {
            if (off + 44 > len) revert CsdTxMalformed();
            if (i == 0 && bytes32(txRaw[off:off + 32]) == bytes32(0) && _readU32LE(txRaw, off + 32) == type(uint32).max)
                revert CsdCoinbaseNotSupported();
            off += 36;
            uint256 scriptLen = _readU64LE(txRaw, off); off += 8;
            if (scriptLen > len - off) revert CsdTxMalformed();
            off += scriptLen;
        }

        if (off + 8 > len) revert CsdTxMalformed();
        uint256 outputCount = _readU64LE(txRaw, off); off += 8;
        bytes20 expectedScript = bytes20(expectedScriptHash);
        bool paid = false;
        for (uint256 i = 0; i < outputCount; i++) {
            if (off + 28 > len) revert CsdTxMalformed();
            uint256 value = _readU64LE(txRaw, off); off += 8;
            bytes20 script = bytes20(txRaw[off:off + 20]); off += 20;
            if (!paid && script == expectedScript && value >= expectedAmount) paid = true;
        }

        if (off + 8 > len) revert CsdTxMalformed();
        off += 4; // locktime
        uint256 variant = _readU32LE(txRaw, off); off += 4;
        if (variant == 1) {            // Propose { domain, payload_hash, uri, expires_epoch }
            off = _skipString(txRaw, off);
            if (off + 32 > len) revert CsdTxMalformed();
            off += 32;
            off = _skipString(txRaw, off);
            if (off + 8 > len) revert CsdTxMalformed();
            off += 8;
        } else if (variant == 2) {     // Attest { proposal_id, score, confidence }
            if (off + 40 > len) revert CsdTxMalformed();
            off += 40;
        } else if (variant != 0) {     // None
            revert CsdTxMalformed();
        }
        if (off != len) revert CsdTxMalformed();
        if (!paid) revert CsdPaymentOutputNotFound();
    }

    function _skipString(bytes calldata data, uint256 off) internal pure returns (uint256) {
        if (off + 8 > data.length) revert CsdTxMalformed();
        uint256 n = _readU64LE(data, off); off += 8;
        if (n > data.length - off) revert CsdTxMalformed();
        return off + n;
    }

    function _readU32LE(bytes calldata data, uint256 off) internal pure returns (uint32 v) {
        if (off + 4 > data.length) revert CsdTxMalformed();
        for (uint256 i = 0; i < 4; i++) v |= uint32(uint8(data[off + i])) << uint32(i * 8);
    }

    // Walk merkle branch: dsha256(sibling || cur) or dsha256(cur || sibling)
    function _csdMerkleRoot(
        bytes32 txid,
        CsdMerkleStep[] calldata branch
    ) internal pure returns (bytes32) {
        bytes32 cur = txid;
        for (uint i = 0; i < branch.length; i++) {
            bytes32 h = branch[i].hash;
            cur = branch[i].isLeft
                ? sha256(abi.encodePacked(sha256(abi.encodePacked(h, cur))))
                : sha256(abi.encodePacked(sha256(abi.encodePacked(cur, h))));
        }
        return cur;
    }

    // dsha256 of: version(4le) + prev(32) + merkle(32) + time(8le) + bits(4le) + nonce(4le)
    function _csdHeaderHash(CsdBlockHeader calldata h) internal pure returns (bytes32) {
        return sha256(abi.encodePacked(sha256(abi.encodePacked(
            _u32LE(h.version),
            h.prev,
            h.merkle,
            _u64LE(h.time),
            _u32LE(h.bits),
            _u32LE(h.nonce)
        ))));
    }

    // bits_to_target_bytes (compute-substrate src/chain/pow.rs); invalid encodings revert
    function _bitsToTarget(uint32 bits) internal pure returns (uint256) {
        uint256 exp  = bits >> 24;
        uint256 mant = bits & 0xFFFFFF;
        if (exp == 0 || exp > 32 || mant == 0 || (mant & 0x800000) != 0) revert CsdBitsInvalid();
        uint256 target = exp > 3 ? mant << (8 * (exp - 3)) : mant >> (8 * (3 - exp));
        if (target == 0) revert CsdBitsInvalid();
        return target;
    }

    // ── Byte helpers ──────────────────────────────────────────────────────────

    function _readU64LE(bytes calldata data, uint256 off) internal pure returns (uint64 v) {
        require(off + 8 <= data.length, "CSD_U64_OVF");
        for (uint256 i = 0; i < 8; i++) v |= uint64(uint8(data[off + i])) << uint64(i * 8);
    }

    function _u32LE(uint32 v) internal pure returns (bytes4) {
        return bytes4(abi.encodePacked(uint8(v), uint8(v>>8), uint8(v>>16), uint8(v>>24)));
    }

    function _u64LE(uint64 v) internal pure returns (bytes8) {
        return bytes8(abi.encodePacked(
            uint8(v), uint8(v>>8), uint8(v>>16), uint8(v>>24),
            uint8(v>>32), uint8(v>>40), uint8(v>>48), uint8(v>>56)
        ));
    }

    function _cpCalldata(
        bytes calldata src, uint256 srcOff,
        bytes memory dst, uint256 dstOff,
        uint256 n
    ) internal pure {
        // Copy in 32-byte word chunks for efficiency, byte-by-byte only for the tail
        assembly {
            let srcPtr := add(src.offset, srcOff)
            let dstPtr := add(add(dst, 32), dstOff)
            let end    := add(srcPtr, n)
            for {} lt(add(srcPtr, 31), end) { srcPtr := add(srcPtr, 32) dstPtr := add(dstPtr, 32) } {
                mstore(dstPtr, calldataload(srcPtr))
            }
            // Tail: remaining bytes < 32
            for {} lt(srcPtr, end) { srcPtr := add(srcPtr, 1) dstPtr := add(dstPtr, 1) } {
                mstore8(dstPtr, byte(0, calldataload(srcPtr)))
            }
        }
    }

    // ── ECDSA recovery ────────────────────────────────────────────────────────

    // Secp256k1 half-order — s must be in the lower half to prevent malleability
    uint256 private constant SECP256K1_HALF_ORDER =
        0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0;

    function _recover(bytes32 digest, bytes calldata sig) internal pure returns (address) {
        if (sig.length != 65) revert BadSignature();
        bytes32 r; bytes32 s; uint8 v;
        assembly {
            r := calldataload(sig.offset)
            s := calldataload(add(sig.offset, 32))
            v := byte(0, calldataload(add(sig.offset, 64)))
        }
        if (v < 27) v += 27;
        if (v != 27 && v != 28) revert BadSignature();
        // L7: Reject upper-half s values (EIP-2 / OpenZeppelin ECDSA practice)
        if (uint256(s) > SECP256K1_HALF_ORDER) revert BadSignature();
        address signer = ecrecover(digest, v, r, s);
        if (signer == address(0)) revert BadSignature();
        return signer;
    }
}
